-- 21: ďalšie kategórie podľa druhu vozidla a kategória „Iné“ pre všetky vozidlá (9. 11. 2026). Spúšťa sa po 18.
-- Kategórie s vtypes sa zobrazia len pri danom druhu vozidla; „Iné“ (vtypes null) pri všetkých.
begin;
update public.categories set vtypes = '{osobne,dodavky}' where id = 'tuz';
update public.categories set vtypes = '{osobne}' where id = 'kab';
update public.categories set vtypes = '{dodavky}' where id = 'dnp';
update public.categories set vtypes = '{dodavky}' where id = 'obv';
update public.categories set vtypes = '{nakladne}' where id = 'nkb';
update public.categories set vtypes = '{nakladne,autobusy}' where id = 'nvz';
update public.categories set vtypes = '{nakladne}' where id = 'npr';
update public.categories set vtypes = '{autobusy}' where id = 'bin';
update public.categories set vtypes = '{motorky}' where id = 'mvy';
update public.categories set vtypes = '{motorky}' where id = 'mjz';
update public.categories set vtypes = '{motorky}' where id = 'atv';
commit;
